use std::ffi::{CStr, CString};
use std::os::raw::c_char;

extern "C" {
    fn probe_native_early_prefill_enabled() -> i32;
    fn probe_set_crt_early_prefill(value: *const c_char) -> i32;
    fn probe_get_crt_early_prefill() -> *const c_char;
}

const KEY: &str = "QRT_QWEN36_WHOLE_PROVIDER_EARLY_PREFILL_STREAM_CALLBACK";

fn set_crt(value: &str) {
    let text = CString::new(value).unwrap();
    assert_eq!(unsafe { probe_set_crt_early_prefill(text.as_ptr()) }, 0);
}

fn observe(stage: &str, expected_os: Option<&str>, expected_crt: Option<&str>, expected_enabled: bool) {
    let os = std::env::var(KEY).ok();
    let pointer = unsafe { probe_get_crt_early_prefill() };
    let crt = if pointer.is_null() { None } else {
        Some(unsafe { CStr::from_ptr(pointer) }.to_str().unwrap().to_owned())
    };
    let enabled = unsafe { probe_native_early_prefill_enabled() } != 0;
    // Values are deliberately only ASCII 0/1/null; debug strings are JSON strings.
    println!("{{\"kind\":\"windows_runtime_environment_probe\",\"stage\":{stage:?},\"os_value\":{},\"crt_value\":{},\"actual_core_early_prefill_enabled\":{enabled}}}",
        os.as_ref().map(|v| format!("{v:?}")).unwrap_or("null".to_owned()),
        crt.as_ref().map(|v| format!("{v:?}")).unwrap_or("null".to_owned()));
    assert_eq!(os.as_deref(), expected_os);
    assert_eq!(crt.as_deref(), expected_crt);
    assert_eq!(enabled, expected_enabled);
}

fn main() {
    assert_eq!(std::env::var("COMPUTERNAME").unwrap().to_ascii_lowercase(), "baiying");
    // Match foreground service startup before any explicit CRT environment
    // access in this test. The wrapper supplies no inherited QRT profile.
    assert!(std::env::var(KEY).is_err());
    std::env::set_var(KEY, "1");
    observe("first_rust_assignment_before_crt_access", Some("1"), None, false);
    set_crt("0");
    observe("initial_crt_assignment", Some("0"), Some("0"), false);
    std::env::set_var(KEY, "1");
    observe("rust_assignment_stale_core", Some("1"), Some("0"), false);
    set_crt("1");
    observe("crt_assignment_visible_to_both", Some("1"), Some("1"), true);
    std::env::set_var(KEY, "0");
    observe("rust_override_stale_core", Some("0"), Some("1"), true);
    std::env::remove_var(KEY);
    observe("rust_removal_stale_core", None, Some("1"), true);
    set_crt("");
    observe("crt_removal_visible_to_both", None, None, false);
    println!("{{\"kind\":\"windows_runtime_environment_probe_summary\",\"cases\":7,\"stale_core_cases\":4,\"actual_core_function_used\":true,\"model_loaded\":false,\"gpu_work_submitted\":false}}");
}
